using System.Collections.Generic;using System.Text;public class Solution{public string DecodeString(string s){var nums=new Stack<int>();var prev=new Stack<StringBuilder>();var cur=new StringBuilder();int n=0;foreach(char c in s){if(char.IsDigit(c))n=n*10+c-'0';else if(c=='['){nums.Push(n);prev.Push(cur);cur=new StringBuilder();n=0;}else if(c==']'){string x=cur.ToString();cur=prev.Pop();int k=nums.Pop();while(k-->0)cur.Append(x);}else cur.Append(c);}return cur.ToString();}}
